#!/usr/bin/env bash
set -eu

# All arguments are generated by install.js; no shell code or JSON is evaluated.
job_file="$1"
install_dir="$2"
stage_dir="$3"
backup_dir="$4"
job_dir="$5"
token="$6"
parent_pid="$7"
timeout_ms="$8"
rename_timeout_ms="$9"
shift 9
launch_args=("$@")
app_name=streamlink-twitch-gui
ready_file="$job_dir/ready"
ack_file="$job_dir/healthy"
status_file="$job_dir/status.json"
new_pid=
swapped=0
old_moved=0
parent_exited=0
done_install=0

status() {
  printf '{"state":"%s","code":"%s"}\n' "$1" "$2" > "$status_file"
}

launch_old() {
  (cd "$install_dir" && env -u STGUI_UPDATE_JOB -u STGUI_UPDATE_TOKEN \
    STGUI_UPDATE_ROLLBACK="$job_file" \
    setsid "$install_dir/$app_name" "${launch_args[@]}" \
    < /dev/null >> "$job_dir/rollback.log" 2>&1) &
}

rollback() {
  local result=$?
  trap - EXIT
  if [ "$done_install" = 1 ]; then return; fi
  if [ -n "$new_pid" ]; then
    kill -TERM -- "-$new_pid" 2>/dev/null || true
    sleep 0.2
    kill -KILL -- "-$new_pid" 2>/dev/null || true
  fi
  if [ "$old_moved" = 1 ]; then
    if [ "$swapped" = 1 ] && [ -d "$install_dir" ]; then
      mv -T -- "$install_dir" "$job_dir/failed-app" || {
        status failed UPDATE_ROLLBACK
        exit 1
      }
    fi
    if mv -T -- "$backup_dir" "$install_dir"; then
      status rolled-back UPDATE_INSTALL
      launch_old
    else
      status failed UPDATE_ROLLBACK
    fi
  elif [ "$parent_exited" = 1 ] && [ -x "$install_dir/$app_name" ]; then
    status rolled-back UPDATE_INSTALL
    launch_old
  else
    status failed UPDATE_INSTALL
  fi
  exit "${result:-1}"
}

case "$token" in *[!a-f0-9]*|'') exit 1;; esac
[ "${#token}" = 64 ] || exit 1
case "$parent_pid:$timeout_ms:$rename_timeout_ms" in *[!0-9:]*) exit 1;; esac
[ "$parent_pid" -gt 1 ] && [ "$parent_pid" != "$$" ] || exit 1
[ "$timeout_ms" -ge 100 ] && [ "$timeout_ms" -le 300000 ] || exit 1
[ "$rename_timeout_ms" -ge 100 ] && [ "$rename_timeout_ms" -le 60000 ] || exit 1
[ -d "$install_dir" ] && [ -d "$stage_dir" ] && [ -d "$job_dir" ] || exit 1
[ ! -e "$backup_dir" ] && [ -f "$job_file" ] || exit 1
parent_dir="$(dirname -- "$install_dir")"
[ "$(dirname -- "$stage_dir")" = "$parent_dir" ] || exit 1
[ "$(dirname -- "$backup_dir")" = "$parent_dir" ] || exit 1
[ "$(dirname -- "$job_dir")" = "$parent_dir" ] || exit 1
[ "$stage_dir" = "$job_dir-stage" ] && [ "$backup_dir" = "$job_dir-backup" ] || exit 1
[ "$job_file" = "$job_dir/job.json" ] && [ -x "$stage_dir/$app_name" ] || exit 1
command -v setsid > /dev/null || exit 1
trap rollback EXIT
printf '%s' "$token" > "$ready_file"

# A helper which cannot observe the old app exiting must leave it untouched.
for ((attempt = 0; attempt < 1200; attempt++)); do
  if ! kill -0 "$parent_pid" 2>/dev/null; then break; fi
  sleep 0.1
done
if kill -0 "$parent_pid" 2>/dev/null; then exit 1; fi
parent_exited=1
# NW.js browser/profile teardown can outlive its renderer's Node PID briefly.
sleep 0.5

for ((attempt = 0; attempt < (rename_timeout_ms + 99) / 100; attempt++)); do
  if mv -T -- "$install_dir" "$backup_dir" 2>/dev/null; then old_moved=1; break; fi
  sleep 0.1
done
[ "$old_moved" = 1 ] || exit 1
mv -T -- "$stage_dir" "$install_dir"
swapped=1

(cd "$install_dir" && exec env -u STGUI_UPDATE_ROLLBACK \
  STGUI_UPDATE_JOB="$job_file" STGUI_UPDATE_TOKEN="$token" \
  setsid "$install_dir/$app_name" "${launch_args[@]}" \
  < /dev/null >> "$job_dir/startup.log" 2>&1) &
new_pid=$!
for ((attempt = 0; attempt < (timeout_ms + 99) / 100; attempt++)); do
  if [ -f "$ack_file" ] && [ "$(cat -- "$ack_file")" = "$token" ]; then
    done_install=1
    status succeeded ""
    rm -f -- "$job_dir/update.tar.gz"
    exit 0
  fi
  if ! kill -0 "$new_pid" 2>/dev/null; then exit 1; fi
  sleep 0.1
done
exit 1
